import sys

def solve(x):
    # Check if x can be expressed as a XOR b = (a + b) / 2
    # This implies a + b = 2 * (a XOR b)
    # Let's try to find such a and b
    for a in range(1, 2**32):
        b = 2 * x - a
        if b > 0 and a ^ b == x:
            return a, b
    return -1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    xs = map(int, data[1:])

    results = []
    for x in xs:
        result = solve(x)
        if result == -1:
            results.append("-1")
        else:
            results.append(f"{result[0]} {result[1]}")

    print("\n".join(results))

if __name__ == "__main__":
    main()
